    },
    {
      "scene_number": 3,
      "caption": "Patrol armour echoes in the square.",
      "visual_description": "Four armored patrolmen with halberds march past a dry fountain; the party hides behind a fallen statue of a griffin.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "acrobat", "armored_patrol"]
    },
    {
      "scene_number": 4,
      "caption": "The cursed tower looms over the alley.",
      "visual_description": "A twisted spire with blue glow seeping from broken windows, ivy gripping the stones, a locked iron door at the base.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "acrobat"]
    },
    {
      "scene_number": 5,
      "caption": "The acrobat opens a high window.",
      "visual_description": "Acrobat balances on a rusted gutter while prying a small window open with a mirror shard; others wait below.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "acrobat"]
    },
    {
      "scene_number": 6,
      "caption": "Inside the tower: a hall of mirrors.",
      "visual_description": "Candlelight reflected a hundred times in cracked mirrors; the party steps cautiously through the shimmering floor.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "acrobat"]
    },
    {
      "scene_number": 7,
      "caption": "Townsfolk whisper from a cellar grate.",
      "visual_description": "A metal grate in the mirror hall floor; pale faces and hands reach up, begging for rescue.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "acrobat", "frightened_townsfolk"]
    },
    {
      "scene_number": 8,
      "caption": "A magic door bars the upper stair.",
      "visual_description": "Door etched with floating runes that pulse red; the magic_helper steps forward to read them.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "acrobat"]
    },
    {
      "scene_number": 9,
      "caption": "The sleepy official wakes a hidden mechanism.",
      "visual_description": "Official yawns and leans on a dusty gargoyle statue; the gargoyle's eyes glow and the door clicks open.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "acrobat"]
    },
    {
      "scene_number": 10,
      "caption": "Top of the tower: the rescue target.",
      "visual_description": "A round room with a glowing crystal cage; inside, a young royal waits with a torn banner wrapped around them.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "acrobat", "rescued_royal"]
    },
    {
      "scene_number": 11,
      "caption": "The magic_helper breaks the cage with a crystal key.",
      "visual_description": "Key turns in the lock; the crystal bars dissolve into sparks, and the rescued_royal steps free.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "acrobat", "rescued_royal"]
    },
    {
      "scene_number": 12,
      "caption": "Dragons rumored above the tower.",
      "visual_description": "Through a broken roof, a shadow with wings passes across the moon; the party freezes.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "acrobat", "rescued_royal"]
    },
    {
      "scene_number": 13,
      "caption": "The party descends through the mirror hall.",
      "visual_description": "Reflections of the group multiply on all sides; the rescued_royal clutches the torn banner.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "acrobat", "rescued_royal"]
    },
    {
      "scene_number": 14,
      "caption": "Patrols block the old plaza.",
      "visual_description": "Six armored figures stand in formation before the central fountain; the scout signals a flanking route.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "acrobat", "rescued_royal", "armored_patrol"]
    },
    {
      "scene_number": 15,
      "caption": "The acrobat creates a diversion.",
      "visual_description": "Acrobat swings across a rope tied to a lamp bracket, toppling a stack of barrels to scatter the patrol.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "acrobat", "rescued_royal", "armored_patrol"]
    },
    {
      "scene_number": 16,
      "caption": "Bridge controls under the arch.",
      "visual_description": "A rusted lever mechanism beside the great stone bridge; the sleepy official pulls the lever with a grunt.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "acrobat", "rescued_royal"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge lowers across the chasm.",
      "visual_description": "Wooden drawbridge descends with a groan over a deep ravine; the first light of sunrise hits the far side.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "acrobat", "rescued_royal"]
    },
    {
      "scene_number": 18,
      "caption": "Escape into the sunrise.",
      "visual_description": "The whole party runs across the bridge; the city and tower are silver behind them, the road ahead golden.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "acrobat", "rescued_royal"]
    }
  ]
}
